int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *perm = (int *)malloc((N + 1) * sizeof(int));
    int *used = (int *)calloc(N + 1, sizeof(int));
    int *next = (int *)malloc((N + 1) * sizeof(int));

    for (int r = 1; r <= N; r++) {
        int x = ((r - 1) * M) % N + 1;
        perm[r] = x;
        used[x] = 1;
    }

    int ptr = 1;
    for (int i = 1; i <= N; i++) {
        while (ptr <= N && used[ptr]) ptr++;
        next[i] = ptr;
        ptr++;
    }

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= M; j++) {
            int row = perm[i];
            int val = row + (j - 1) * N;
            if (j > 1) printf(" ");
            printf("%d", val);
        }
        printf("\n");
    }

    free(perm);
    free(used);
    free(next);
    return 0;
}

