#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // Initial grid:
    // row i contains numbers (i-1)M+1 ... iM
    // We output the grid after the first row rearrangement.
    //
    // Construction:
    // Put number x = (r-1)M + c into position:
    //   row = c
    //   col = r
    // i.e. transpose the N x M block structure conceptually.
    //
    // After that:
    // - In each column, numbers have distinct target rows modulo construction,
    //   so columns can be permuted to place each number into its target row.
    // - Then each row can be permuted to place numbers into final target columns.
    //
    // This first-step arrangement is enough to describe one valid solution.

    vector<vector<int>> a(N, vector<int>(M));

    for (int r = 0; r < N; ++r) {
        for (int c = 0; c < M; ++c) {
            int nr = c % N;
            int nc = (r + c / N) % M;
            a[nr][nc] = r * M + c + 1;
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            if (j) cout << ' ';
            cout << a[i][j];
        }
        cout << '\n';
    }

    return 0;
}

