public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        int[][] grid = new int[N][M];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < M; j++) {
                grid[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        // Step 1: Rearrange each row so that numbers are grouped by target row
        for (int i = 0; i < N; i++) {
            Arrays.sort(grid[i]);
        }

        // Step 2: Rearrange each column so each column has one from each target row
        // We'll do this by sorting each column based on the target row of each number
        for (int j = 0; j < M; j++) {
            int[] col = new int[N];
            for (int i = 0; i < N; i++) {
                col[i] = grid[i][j];
            }
            // Sort column by the target row index
            Arrays.sort(col);
            for (int i = 0; i < N; i++) {
                grid[i][j] = col[i];
            }
        }

        // Step 3: Rearrange each row to the exact target order
        for (int i = 0; i < N; i++) {
            int[] targetRow = new int[M];
            for (int j = 0; j < M; j++) {
                targetRow[j] = M * i + j + 1;
            }
            // We need to permute grid[i] to match targetRow
            // Since we know targetRow is sorted ascending, sort grid[i]
            Arrays.sort(grid[i]);
        }

        // Output result
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                sb.append(grid[i][j]);
                if (j < M - 1) sb.append(" ");
            }
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
}

