public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        StringBuilder out = new StringBuilder();

        // Initial grid:
        // a[i][j] = i + 1 + N * j   (0-indexed i, j)
        // This is a permutation of 1..N*M.
        //
        // Step 1 (row permutations):
        // In row i, cyclically shift left by i positions.
        // After this, value at (i, j) becomes:
        //   i + 1 + N * ((i + j) mod M)
        //
        // Step 2 (column permutations):
        // In column j, sort by row target, i.e. move each value to row
        //   r = (i + j) mod M
        // This works because after step 1 the residue modulo M determines the final row.
        //
        // A simpler explicit construction of the intermediate matrix after step 1:
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                int val = i + 1 + N * ((i + j) % M);
                if (j > 0) out.append(' ');
                out.append(val);
            }
            out.append('\n');
        }

        System.out.print(out);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

