public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        int[][] grid = new int[N][M];
        for (int i = 0; i < N; i++)
            for (int j = 0; j < M; j++)
                grid[i][j] = sc.nextInt();
        // Phase 1: rearrange each row so value v goes to column (v-1)%M
        int[][] phase1 = new int[N][M];
        for (int i = 0; i < N; i++) {
            int[] row = grid[i].clone();
            int[] result = new int[M];
            boolean[] used = new boolean[M];
            // First pass: assign v to col (v-1)%M if free
            int[] pending = new int[M]; int pc = 0;
            for (int v : row) {
                int col = (v-1) % M;
                if (!used[col]) { result[col] = v; used[col] = true; }
                else pending[pc++] = v;
            }
            // Second pass: assign pending to free cols
            int fi = 0;
            for (int k = 0; k < pc; k++) {
                while (used[fi]) fi++;
                result[fi] = pending[k]; used[fi] = true; fi++;
            }
            phase1[i] = result;
        }
        // Phase 2: sort each column
        int[][] phase2 = new int[N][M];
        for (int j = 0; j < M; j++) {
            int[] col = new int[N];
            for (int i = 0; i < N; i++) col[i] = phase1[i][j];
            Arrays.sort(col);
            for (int i = 0; i < N; i++) phase2[i][j] = col[i];
        }
        // Phase 3: sort each row
        int[][] phase3 = new int[N][M];
        for (int i = 0; i < N; i++) {
            phase3[i] = phase2[i].clone();
            Arrays.sort(phase3[i]);
        }
        // Verify
        boolean ok = true;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < M; j++)
                if (phase3[i][j] != M*i+j+1) ok = false;
        // Output phase1, phase2, phase3 arrangements
        // Need to output the permutations
        // For each phase, output the arrangement of each row/column
        StringBuilder sb = new StringBuilder();
        // Phase 1: for each row, output the permutation
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (j > 0) sb.append(' ');
                sb.append(phase1[i][j]);
            }
            sb.append('\n');
        }
        sb.append('\n');
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (j > 0) sb.append(' ');
                sb.append(phase2[i][j]);
            }
            sb.append('\n');
        }
        sb.append('\n');
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (j > 0) sb.append(' ');
                sb.append(phase3[i][j]);
            }
